def search_tool(task):
    return "SEARCH"

def file_tool(task):
    return "FILE"

def chat_model(task):
    return "CHAT"

def run_agent(task):
    if "search" in task:
        return search_tool(task)
    if "file" in task:
        return file_tool(task)
    return chat_model(task)

print(run_agent("search file"))
